def fizzbuzz(n):
    resultado = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            resultado.append('FizzBuzz')
        elif i % 3 == 0:
            resultado.append('Fizz')
        elif i % 5 == 0:
            resultado.append('Buzz')
        else:
            resultado.append(str(i))
    return resultado

def es_palindromo(s):
    s_limpia = ''.join(c for c in s if c.isalnum()).lower()
    return s_limpia == s_limpia[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    l = 0
    r = len(lista) - 1
    while l <= r:
        m = (l + r) // 2
        if lista[m] == x:
            return m
        elif lista[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    numeros_romanos = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"),
        (1, "I")
    ]
    resultado = []
    while n > 0:
        for valor, simbolo in numeros_romanos:
            if n >= valor:
                resultado.append(simbolo)
                n -= valor
    return "".join(resultado)

def desde_romano(s):
    numeros = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    i = 0
    while i < len(s):
        valor = numeros[s[i]]
        if i + 1 < len(s) and numeros[s[i + 1]] > valor:
            valor = numeros[s[i + 1]] - numeros[s[i]]
            i += 2
        resultado += valor
        i += 1
    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = None
    max_longitud = -1

    i = 0
    while i < len(lista):
        elemento = lista[i]
        j = i
        while j < len(lista) and lista[j] == elemento:
            j += 1
        longitud = j - i

        if longitud > max_longitud:
            max_elemento = elemento
            max_longitud = longitud
        i = j

    return (max_elemento, max_longitud)

def a_camel(s):
    words = s.split('_')
    return ''.join(word[0].upper() + word[1:] if i > 0 else word for i, word in enumerate(words))

def a_snake(s):
    result = []
    for char in s:
        if char.isupper():
            if result and result[-1].islower():
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for i in range(2, n + 1):
        if all(i % j != 0 for j in range(2, int(i ** 0.5) + 1)):
            primos_list.append(i)
    return primos_list

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar por inicio; si no están ordenados, asegurarlo
    intervalos = sorted(intervalos, key=lambda x: x[0])

    resultados = []

    for inicio, fin in intervalos:
        if not resultados or inicio > resultados[-1][1]:
            resultados.append([inicio, fin])
        else:
            # Fusionar con el último intervalo si tocan o superponen
            resultados[-1][1] = max(resultados[-1][1], fin)

    return resultados

def es_anagrama(a, b):
    def normalizar(texto):
        return sorted(letra for letra in texto.lower() if letra.isalpha())

    return normalizar(a) == normalizar(b)

def comprimir(s):
    if not s:
        return s

    compresion = []
    contador = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            contador += 1
        else:
            compresion.append(s[i - 1])
            compresion.append(str(contador))
            contador = 1
    compresion.append(s[-1])
    compresion.append(str(contador))
    version_comprimida = ''.join(compresion)

    return version_comprimida if len(version_comprimida) < len(s) else s

def balanceado(texto):
    if not texto:
        return True

    contador = 0
    for char in texto:
        if char in '()[]{}':
            if char in '([{':
                contador += 1
            elif char in ')]}':
                contador -= 1
            if contador < 0:
                return False
    return contador == 0

def transpuesta(matriz):
    if not matriz:
        return []
    n = len(matriz)
    resultados = []
    for i in range(len(matriz[0])):
        fila = []
        for j in range(n):
            if matriz[j] and matriz[j][i] is not None:
                fila.append(matriz[j][i])
            else:
                fila.append(None)
        resultados.append(fila)
    return resultados

def raiz_digital(n):
    while n >= 10:
        suma = 0
        while n > 0:
            suma += n % 10
            n //= 10
        n = suma
    return n

def sin_duplicados(lista):
    resultado = []
    for elemento in lista:
        if elemento not in resultado:
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    distinct_values = sorted(set(lista), reverse=True)
    if len(distinct_values) < n:
        return None
    return distinct_values[n - 1]

def formatear_bytes(n):
    if n == 0:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB']
    for i, unit in enumerate(units):
        step = 1024 ** i
        value = n / step
        if value < 1024:
            if value == int(value):
                return f'{int(value)} {unit}'
            else:
                return f'{value:.1f} {unit}'
    return f'{n} B'

def _lotes(lista, tamano):
    if not lista:
        return []
    resultados = []
    inicio = 0
    while inicio < len(lista):
        lote_tamano = tamano if inicio + tamano <= len(lista) else len(lista) - inicio
        resultados.append(lista[inicio:inicio + lote_tamano])
        inicio += tamano
    return resultados
